// src/ls/catalog.ts
// Mock catalog + condition system — ported EXACTLY from from_design/ls-shared.jsx.
// Grades are assigned by Little Soles, not the seller (locked decision).

export type ConditionKey = 'cert' | 'nib' | 'nnb' | 'worn' | 'play';

export type Condition = {
  /** ls.css class key, used to pick the chip variant. */
  cls: 'chip-cert' | 'chip-new' | 'chip-worn' | 'chip-play';
  label: string;
  desc: string;
  /** Only Pristine shows the check tick. */
  check?: boolean;
};

export const CONDITIONS: Record<ConditionKey, Condition> = {
  cert: {
    cls: 'chip-cert',
    label: 'Pristine',
    check: true,
    desc: 'Like new. Barely a step in them.',
  },
  nib: {
    cls: 'chip-new',
    label: 'New in Box',
    desc: 'Brand new and unworn, with the original box.',
  },
  nnb: {
    cls: 'chip-new',
    label: 'New, No Box',
    desc: 'Brand new and unworn — box not included.',
  },
  worn: {
    cls: 'chip-worn',
    label: 'Gently Worn',
    desc: 'Light, even wear with plenty of life left.',
  },
  play: {
    cls: 'chip-play',
    label: 'Play Condition',
    desc: 'Well-loved and ready for the playground.',
  },
};

export type CatalogItem = {
  brand: string;
  name: string;
  price: number;
  cond: ConditionKey;
};

export type CatalogId =
  | 'j4'
  | 'af1'
  | 'nb550'
  | 'samba'
  | 'panda'
  | 'j1'
  | 'vans'
  | 'chuck';

