// src/ls/config.ts
// Integration config for the Little Soles backend API.
// PURELY ADDITIVE — nothing here runs unless a screen opts in via src/ls/data.ts.

/**
 * Base URL for the ls-api backend (no trailing slash, no /api suffix —
 * the api client appends `/api/...` paths itself).
 *
 * Override with EXPO_PUBLIC_API_URL. On a real phone in Expo Go, localhost
 * points at the PHONE, not your dev machine — so you MUST set this to the
 * machine's Tailscale or LAN IP, e.g.:
 *   EXPO_PUBLIC_API_URL=http://100.103.56.38:4100
 * (web/simulator can use the localhost default below.)
 */
export const API_BASE_URL: string =
  process.env.EXPO_PUBLIC_API_URL ?? 'http://localhost:4100';

/**
 * Master switch. When false (the default), the app keeps using the mock
 * CATALOG from catalog.ts and never touches the network. Flip it on with
 * EXPO_PUBLIC_USE_API=true once the backend is reachable.
 */
export const USE_API: boolean = process.env.EXPO_PUBLIC_USE_API === 'true';

/**
 * Google OAuth *Web* client id (from Google Cloud Console). The Google sign-in
 * button only renders when this is set — so the app never crashes or shows a
 * dead button before CJ creates the client id. See docs/social-auth-setup.md.
 *
 * In Expo Go, AuthSession uses this web client id and Expo's auth proxy; the
 * id token it returns is what the backend verifies (audience = this id).
 */
export const GOOGLE_CLIENT_ID: string | undefined =
  process.env.EXPO_PUBLIC_GOOGLE_CLIENT_ID || undefined;
