import React, { useState } from 'react';
import { View, Text, Pressable, StyleSheet, TextInput, ActivityIndicator, Platform, Alert } from 'react-native';
import { useRouter } from 'expo-router';

import { Screen, ScreenBody, TopBar, Button, dualCTA } from '@/ls/ui';
import { Icon } from '@/ls/icons';
import { colors, fonts, text, letterSpacingPx } from '@/ls/theme';
import { children, alerts, ApiError } from '@/ls/api';

const SIZES = ['4C', '5C', '6C', '7C', '8C', '9C', '10C', '11C', '12C', '13C', '1Y', '2Y'];

function notify(title: string, message?: string) {
  if (Platform.OS === 'web') {
    if (typeof window !== 'undefined') window.alert(message ? `${title}\n\n${message}` : title);
    return;
  }
  Alert.alert(title, message);
}

// Add child's size. Creates a real Child (and optional size alert) via the API.
export default function AddSizeScreen() {
  const router = useRouter();
  const [childName, setChildName] = useState('');
  // A kid wears different sizes across brands and types, and grows fast, so the
  // profile holds 1 to 4 sizes. Selection is a toggle; 10C is the design default.
  const [selected, setSelected] = useState<string[]>(['10C']);
  const [alertOn, setAlertOn] = useState(true);
  const [busy, setBusy] = useState(false);

  const MAX_SIZES = 4;

  const toggleSize = (s: string) => {
    setSelected((prev) => {
      if (prev.includes(s)) {
        // Keep at least one size selected.
        return prev.length > 1 ? prev.filter((x) => x !== s) : prev;
      }
      if (prev.length >= MAX_SIZES) {
        notify('Up to 4 sizes', 'Remove one to add another. Four covers the brands and growth room most kids need.');
        return prev;
      }
      // Preserve the grid order so the chips read left to right.
      return SIZES.filter((x) => prev.includes(x) || x === s);
    });
  };

  const goShop = () => router.replace('/(tabs)');

  const onSave = async () => {
    const name = childName.trim();
    if (!name) {
      notify('Add a name', 'Enter your child’s name so we can label their sizes.');
      return;
    }
    if (selected.length === 0) {
      notify('Pick a size', 'Choose at least one size so we know what to watch for.');
      return;
    }
    setBusy(true);
    try {
      // The backend creates one size alert per size on child create (idempotent),
      // so we no longer create alerts here. The toggle keeps alerts on by default;
      // when off, we deactivate the child's alerts after the create.
      const res = await children.create({ name, sizes: selected });
      if (!alertOn) {
        try {
          const { alerts: all } = await alerts.list();
          await Promise.all(
            all
              .filter((a) => a.childId === res.child.id && a.active)
              .map((a) => alerts.toggle(a.id, false)),
          );
        } catch {
          // Alert state is a nice-to-have; don't block shopping if it fails.
        }
      }
      router.replace('/(tabs)');
    } catch (e) {
      const msg = e instanceof ApiError ? e.message : 'Could not save the sizes. Please try again.';
      notify('Something went wrong', msg);
    } finally {
      setBusy(false);
    }
  };

  return (
    <Screen>
      <TopBar
        left={
          <Pressable onPress={() => router.back()} hitSlop={8}>
            <Icon.chevL w={22} h={22} strokeWidth={2} />
          </Pressable>
        }
        right={
          <Pressable onPress={goShop} hitSlop={8}>
            <Text style={styles.skip}>Skip</Text>
          </Pressable>
        }
      />

      {/* 3-step progress sits under the bar, centered */}
      <View style={styles.progressWrap}>
        <View style={styles.progress}>
          {[1, 1, 0].map((on, i) => (
            <View
              key={i}
              style={[styles.progressSeg, { backgroundColor: on ? colors.black : colors.line }]}
            />
          ))}
        </View>
      </View>

      <ScreenBody contentContainerStyle={styles.body}>
        <Text style={text.hXl}>Add your{'\n'}child&rsquo;s sizes</Text>
        <Text style={[text.body, styles.sub]}>
          Kids wear different sizes across brands and grow fast. Pick every size
          that fits, and we&rsquo;ll alert you the moment a pair drops.
        </Text>

        <View style={styles.field}>
          <Text style={styles.label}>Child&rsquo;s name</Text>
          <View style={styles.input}>
            <TextInput
              style={styles.inputText}
              value={childName}
              onChangeText={setChildName}
              placeholder="e.g. Mia"
              placeholderTextColor={colors.gray2}
              autoCapitalize="words"
            />
          </View>
        </View>

        <View style={styles.sizeSection}>
          <Text style={styles.label}>Current sizes (pick up to 4)</Text>
          <View style={styles.sizeGrid}>
            {SIZES.map((s) => {
              const sel = selected.includes(s);
              return (
                <Pressable
                  key={s}
                  onPress={() => toggleSize(s)}
                  accessibilityRole="button"
                  accessibilityState={{ selected: sel }}
                  style={[styles.sizeCell, sel && styles.sizeCellSel]}
                >
                  <Text style={styles.sizeText}>{s}</Text>
                </Pressable>
              );
            })}
          </View>
        </View>

        <Pressable style={styles.alertRow} onPress={() => setAlertOn((v) => !v)}>
          <Icon.bell w={19} h={19} strokeWidth={1.9} />
          <Text style={styles.alertText}>Alert me when new pairs drop in {selected.join(', ')}</Text>
          <View style={[styles.toggle, alertOn ? styles.toggleOn : styles.toggleOff]}>
            <View style={[styles.knob, alertOn ? styles.knobOn : styles.knobOff]} />
          </View>
        </Pressable>

        <Pressable style={styles.addAnother}>
          <Icon.plus w={16} h={16} strokeWidth={2.2} stroke={colors.gray} />
          <Text style={styles.addAnotherText}>Add another child</Text>
        </Pressable>
      </ScreenBody>

      <View style={dualCTA}>
        <Button
          label={busy ? 'Saving…' : 'Start shopping'}
          onPress={onSave}
          disabled={busy}
          right={busy ? <ActivityIndicator color={colors.white} size="small" /> : undefined}
        />
      </View>
    </Screen>
  );
}

