// src/ls/social-auth.tsx
// "Continue with Apple" and "Continue with Google" — both runtime-guarded so
// the app ALWAYS loads in Expo Go and never crashes or shows a dead button.
//
// Apple  : expo-apple-authentication. Works in Expo Go on iOS. Button renders
//          only when AppleAuthentication.isAvailableAsync() is true (iOS 13+).
//          On Android / web / unsupported it simply hides.
// Google : expo-auth-session Google provider. Works in Expo Go via the web
//          client id + Expo's auth proxy.
//
//          IMPORTANT: Google.useIdTokenAuthRequest THROWS synchronously when no
//          client id is configured (verified on web — it crashes the screen).
//          A hook can't be conditional, so we NEVER call it from the shared
//          controller. Instead it lives in useGoogleAuth(), which is only
//          mounted (via <GoogleButton>) when GOOGLE_CLIENT_ID is present. No
//          id -> the hook never runs -> no crash, button just hides.
//
// Both paths end the same way: verify the id token on the backend (auth.oauth),
// then drive the existing session flow exactly like login — setUser +
// router.replace('/(tabs)').

import { useCallback, useEffect, useState } from 'react';
import { Platform } from 'react-native';
import { useRouter } from 'expo-router';
import * as WebBrowser from 'expo-web-browser';
import * as AppleAuthentication from 'expo-apple-authentication';
import * as Google from 'expo-auth-session/providers/google';

import { auth, ApiError } from './api';
import { useSession } from './session';
import { GOOGLE_CLIENT_ID } from './config';

// Required once so the auth popup can dismiss itself on web/Expo Go.
WebBrowser.maybeCompleteAuthSession();

export function friendlyError(e: unknown): string {
  if (e instanceof ApiError) {
    if (e.status === 503) return 'Social sign-in is not set up yet. Use email for now.';
    return e.message;
  }
  return 'Could not sign you in. Please try again.';
}

/** Whether the Google button should be wired up at all. */
export const GOOGLE_ENABLED = !!GOOGLE_CLIENT_ID;

export type AppleState = {
  available: boolean;
  busy: boolean;
  start: () => void;
};

export type SocialAuth = {
  apple: AppleState;
  /** Verify a provider id token on the backend and enter the app. Shared by
   *  the Google button so it routes through the exact same session flow. */
  finish: (provider: 'apple' | 'google', idToken: string, name?: string) => Promise<void>;
  error: string | null;
  setError: (e: string | null) => void;
};

/**
 * Apple controller + the shared finish()/error used by both providers. Safe to
 * call on every platform — it never touches the Google hook.
 */
export function useSocialAuth(): SocialAuth {
  const router = useRouter();
  const { setUser } = useSession();

  const [error, setError] = useState<string | null>(null);
  const [appleAvailable, setAppleAvailable] = useState(false);
  const [appleBusy, setAppleBusy] = useState(false);

  useEffect(() => {
    let alive = true;
    // isAvailableAsync only resolves true on iOS 13+. Anything else hides it.
    if (Platform.OS === 'ios') {
      AppleAuthentication.isAvailableAsync()
        .then((ok) => alive && setAppleAvailable(ok))
        .catch(() => alive && setAppleAvailable(false));
    }
    return () => {
      alive = false;
    };
  }, []);

  const finish = useCallback(
    async (provider: 'apple' | 'google', idToken: string, name?: string) => {
      const res = await auth.oauth({ provider, idToken, name });
      setUser(res.user);
      router.replace('/(tabs)');
    },
    [router, setUser],
  );

  const startApple = useCallback(async () => {
    setError(null);
    setAppleBusy(true);
    try {
      const credential = await AppleAuthentication.signInAsync({
        requestedScopes: [
          AppleAuthentication.AppleAuthenticationScope.FULL_NAME,
          AppleAuthentication.AppleAuthenticationScope.EMAIL,
        ],
      });
      if (!credential.identityToken) {
        throw new Error('No identity token from Apple');
      }
      // Apple only returns the name on the FIRST consent — forward it if present.
      const name = credential.fullName
        ? [credential.fullName.givenName, credential.fullName.familyName]
            .filter(Boolean)
            .join(' ')
            .trim() || undefined
        : undefined;
      await finish('apple', credential.identityToken, name);
    } catch (e: any) {
      // User cancelled the native sheet — not an error to show.
      if (e?.code === 'ERR_REQUEST_CANCELED' || e?.code === 'ERR_CANCELED') {
        // no-op
      } else {
        setError(friendlyError(e));
      }
    } finally {
      setAppleBusy(false);
    }
  }, [finish]);

  return {
    apple: { available: appleAvailable, busy: appleBusy, start: startApple },
    finish,
    error,
    setError,
  };
}

export type GoogleState = {
  /** Ready to prompt (discovery loaded). */
  ready: boolean;
  busy: boolean;
  start: () => void;
};

/**
 * Google controller. ONLY call this from a component that is mounted exclusively
 * when GOOGLE_CLIENT_ID exists — otherwise the underlying hook throws.
 * `onFinish`/`onError` come from the parent useSocialAuth so Google uses the
 * same session flow + shared error string.
 */
export function useGoogleAuth(
  onFinish: SocialAuth['finish'],
  onError: (e: string | null) => void,
): GoogleState {
  const [busy, setBusy] = useState(false);
  const [request, response, promptAsync] = Google.useIdTokenAuthRequest({
    // Web client id is what Expo Go / AuthSession uses; also supplied as the iOS
    // client id for standalone iOS builds. CJ can split these later.
    webClientId: GOOGLE_CLIENT_ID,
    iosClientId: GOOGLE_CLIENT_ID,
  });

  useEffect(() => {
    if (!response) return;
    if (response.type === 'success') {
      const idToken = response.params?.id_token as string | undefined;
      if (idToken) {
        onFinish('google', idToken).catch((e) => onError(friendlyError(e)));
      } else {
        onError('Google did not return a sign-in token. Please try again.');
      }
      setBusy(false);
    } else if (response.type === 'error') {
      onError('Could not sign in with Google. Please try again.');
      setBusy(false);
    } else if (response.type === 'cancel' || response.type === 'dismiss') {
      setBusy(false);
    }
  }, [response, onFinish, onError]);

  const start = useCallback(() => {
    onError(null);
    setBusy(true);
    promptAsync().catch(() => {
      onError('Could not open Google sign-in. Please try again.');
      setBusy(false);
    });
  }, [promptAsync, onError]);

  return { ready: !!request, busy, start };
}
