import { useEffect, useState } from 'react';
import { View, Text, Pressable, StyleSheet, ActivityIndicator, Platform, Alert } from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';

import { Screen, ScreenBody, TopBar, PH, Button, Divider, dualCTA } from '@/ls/ui';
import { Icon } from '@/ls/icons';
import { colors, text } from '@/ls/theme';
import { FadeImage } from '@/ls/ui';
import { tapMedium } from '@/ls/haptics';
import { getListing, mockImage } from '@/ls/data';
import { checkout, orders, ApiError, type DisplayListing, type ShippingAddress } from '@/ls/api';
import { useRequireAuth } from '@/ls/session';

// Item price is real from the listing. Shipping/tax are flat demo add-ons.
// LS Protect fee mirrors the server's math (ls-api/src/lib/fees.ts) for
// display; the server recomputes it at charge time and is the source of truth.
const LS_PROTECT_RATE = 0.07;
const LS_PROTECT_FLAT = 0.7;
const SHIP = 9.95;
const TAX_RATE = 0.08;

const DEMO_ADDRESS: ShippingAddress = {
  name: 'Demo Parent',
  line1: '148 Mercer St',
  city: 'Brooklyn',
  state: 'NY',
  postalCode: '11211',
  country: 'US',
};

function notify(title: string, message?: string) {
  if (Platform.OS === 'web') {
    if (typeof window !== 'undefined') window.alert(message ? `${title}\n\n${message}` : title);
    return;
  }
  Alert.alert(title, message);
}

export default function CheckoutScreen() {
  const router = useRouter();
  const { listingId } = useLocalSearchParams<{ listingId?: string }>();
  const requireAuth = useRequireAuth();

  const [item, setItem] = useState<DisplayListing | null>(null);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    let alive = true;
    if (!listingId) {
      setLoading(false);
      return;
    }
    getListing(String(listingId))
      .then((row) => {
        if (alive) setItem(row);
      })
      .finally(() => {
        if (alive) setLoading(false);
      });
    return () => {
      alive = false;
    };
  }, [listingId]);

  const itemPrice = item?.price ?? 0;
  const lsProtect = +(itemPrice * LS_PROTECT_RATE + LS_PROTECT_FLAT).toFixed(2);
  const tax = +(itemPrice * TAX_RATE).toFixed(2);
  const total = +(itemPrice + lsProtect + SHIP + tax).toFixed(2);

  const placeOrder = async () => {
    if (!item) return;
    if (!requireAuth()) return;
    tapMedium();
    setBusy(true);
    try {
      // 1) payment intent (server simulates Stripe)
      const pi = await checkout.paymentIntent({ listingId: item.id });
      // 2) create the order against that intent
      const res = await orders.create({
        listingId: item.id,
        paymentIntentId: pi.paymentIntentId,
        shippingAddress: DEMO_ADDRESS,
      });
      router.replace(`/confirmation?orderId=${res.order.id}`);
    } catch (e) {
      const msg = e instanceof ApiError ? e.message : 'Could not place your order. Please try again.';
      notify('Checkout failed', msg);
    } finally {
      setBusy(false);
    }
  };

  if (loading) {
    return (
      <Screen>
        <TopBar title="Checkout" bordered left={<Pressable onPress={() => router.back()}><Icon.chevL w={22} h={22} strokeWidth={2} /></Pressable>} />
        <View style={styles.loadingWrap}><ActivityIndicator color={colors.black} /></View>
      </Screen>
    );
  }

  const summary: [string, string][] = [
    ['Item', `$${itemPrice.toFixed(2)}`],
    ['LS Protect', `$${lsProtect.toFixed(2)}`],
    ['Shipping', `$${SHIP.toFixed(2)}`],
    ['Tax', `$${tax.toFixed(2)}`],
  ];

  const photo = item?.imageUrl ? { uri: item.imageUrl } : item ? mockImage(item.sku) : null;

  return (
    <Screen>
      <TopBar
        left={
          <Pressable onPress={() => router.back()}>
            <Icon.chevL w={22} h={22} strokeWidth={2} />
          </Pressable>
        }
        title="Checkout"
        bordered
      />

      <ScreenBody>
        {/* item row */}
        <View style={styles.row}>
          <View style={styles.rowThumb}>
            {photo ? <FadeImage source={photo} resizeMode="contain" style={styles.thumbImg} /> : <PH label="" />}
          </View>
          <View style={styles.rowMain}>
            <Text style={styles.rowTitle}>{item ? `${item.brand}, ${item.name}` : 'Listing'}</Text>
            <Text style={text.meta}>{item ? `Size ${item.size ?? 'one size'}` : ''}</Text>
            <View style={{ marginTop: 2 }}>
              <Text style={styles.rowPrice}>${itemPrice}</Text>
            </View>
          </View>
        </View>

        {/* ship to */}
        <View style={[styles.sec, { paddingBottom: 6 }]}>
          <Text style={[text.eyebrow, styles.secLabel]}>Ship to</Text>
          <View style={styles.cardRow}>
            <Icon.truck w={20} h={20} strokeWidth={1.8} />
            <View style={{ flex: 1 }}>
              <Text style={styles.cardName}>{DEMO_ADDRESS.name}</Text>
              <Text style={[text.meta, { marginTop: 2 }]}>
                {DEMO_ADDRESS.line1}, {DEMO_ADDRESS.city}, {DEMO_ADDRESS.state} {DEMO_ADDRESS.postalCode}
              </Text>
              <Text style={[styles.metaStrong, { marginTop: 6 }]}>Arrives in 5 to 7 days</Text>
            </View>
            <Text style={[styles.link, { color: colors.gray }]}>Edit</Text>
          </View>
        </View>

        {/* payment */}
        <View style={[styles.sec, { paddingTop: 12, paddingBottom: 6 }]}>
          <Text style={[text.eyebrow, styles.secLabel]}>Payment</Text>
          <View style={[styles.cardRow, { alignItems: 'center' }]}>
            <View style={styles.cardChip} />
            <Text style={styles.payText}>Visa ···· 4291</Text>
            <Icon.check w={18} h={18} strokeWidth={2.4} />
          </View>
        </View>

        {/* guarantee */}
        <View style={styles.guarantee}>
          <Icon.shield w={18} h={18} strokeWidth={1.9} />
          <Text style={styles.guaranteeText}>
            <Text style={styles.guaranteeBold}>Covered by LS Protect.</Text> Refund or credit if it’s not as described. Every order.
          </Text>
        </View>

        {/* summary */}
        <View style={[styles.sec, { paddingTop: 6 }]}>
          {summary.map(([l, v]) => (
            <View key={l} style={styles.sumLine}>
              <Text style={styles.sumLabel}>{l}</Text>
              <Text style={styles.sumVal}>{v}</Text>
            </View>
          ))}
          <Divider style={{ marginVertical: 8 }} />
          <View style={styles.totalLine}>
            <Text style={styles.totalLabel}>Total</Text>
            <Text style={styles.totalVal}>${total.toFixed(2)}</Text>
          </View>
        </View>
      </ScreenBody>

      <View style={dualCTA}>
        <Button
          label={busy ? 'Placing order…' : `Place order · $${total.toFixed(2)}`}
          onPress={placeOrder}
          disabled={busy || !item}
          right={busy ? <ActivityIndicator color={colors.white} size="small" /> : undefined}
        />
      </View>
    </Screen>
  );
}

