import { useEffect, useMemo, useState } from 'react';
import { View, Text, Pressable, StyleSheet, ActivityIndicator, Platform, Alert } from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';

import { Screen, ScreenBody, TopBar, PH, Button, dualCTA } from '@/ls/ui';
import { Icon } from '@/ls/icons';
import { colors, text } from '@/ls/theme';
import { FadeImage } from '@/ls/ui';
import { PressableScale } from '@/ls/motion';
import { tapMedium } from '@/ls/haptics';
import { getListing, mockImage } from '@/ls/data';
import { offers, ApiError, type DisplayListing } from '@/ls/api';
import { useRequireAuth } from '@/ls/session';

const QUICK = ['-$5', '+$5', '+$10', 'Match ask'] as const;

function notify(title: string, message?: string) {
  if (Platform.OS === 'web') {
    if (typeof window !== 'undefined') window.alert(message ? `${title}\n\n${message}` : title);
    return;
  }
  Alert.alert(title, message);
}

export default function OfferScreen() {
  const router = useRouter();
  const { listingId } = useLocalSearchParams<{ listingId?: string }>();
  const requireAuth = useRequireAuth();

  const [item, setItem] = useState<DisplayListing | null>(null);
  const [loading, setLoading] = useState(true);
  const [amount, setAmount] = useState(0);
  const [active, setActive] = useState(3); // "Match ask" by default
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    let alive = true;
    if (!listingId) {
      setLoading(false);
      return;
    }
    getListing(String(listingId))
      .then((row) => {
        if (!alive) return;
        setItem(row);
        if (row) setAmount(row.price); // start at lowest ask
      })
      .finally(() => {
        if (alive) setLoading(false);
      });
    return () => {
      alive = false;
    };
  }, [listingId]);

  const ask = item?.price ?? 0;
  const bench = useMemo<[string, string][]>(
    () => [
      ['Lowest ask', `$${ask}`],
      ['Suggested', `$${Math.max(1, Math.round(ask * 0.9))}`],
      ['Your offer', `$${amount}`],
    ],
    [ask, amount],
  );

  const applyQuick = (i: number) => {
    setActive(i);
    if (!item) return;
    if (i === 0) setAmount((a) => Math.max(1, a - 5));
    else if (i === 1) setAmount((a) => a + 5);
    else if (i === 2) setAmount((a) => a + 10);
    else setAmount(item.price);
  };

  const submit = async () => {
    if (!item) return;
    if (!requireAuth()) return;
    if (amount < 1) {
      notify('Enter an offer', 'Your offer needs to be at least $1.');
      return;
    }
    tapMedium();
    setBusy(true);
    try {
      await offers.create({ listingId: item.id, amountCents: Math.round(amount * 100) });
      notify('Offer sent', 'The seller has 24 hours to respond. You can track it in Activity.');
      router.replace('/(tabs)/activity');
    } catch (e) {
      const msg = e instanceof ApiError ? e.message : 'Could not send your offer. Please try again.';
      notify('Something went wrong', msg);
    } finally {
      setBusy(false);
    }
  };

  if (loading) {
    return (
      <Screen>
        <TopBar title="Make an Offer" bordered left={<Pressable onPress={() => router.back()}><Icon.chevL w={22} h={22} strokeWidth={2} /></Pressable>} />
        <View style={styles.loadingWrap}><ActivityIndicator color={colors.black} /></View>
      </Screen>
    );
  }

  const photo = item?.imageUrl ? { uri: item.imageUrl } : item ? mockImage(item.sku) : null;

  return (
    <Screen>
      <TopBar
        left={
          <Pressable onPress={() => router.back()}>
            <Icon.chevL w={22} h={22} strokeWidth={2} />
          </Pressable>
        }
        title="Make an Offer"
        bordered
      />

      <ScreenBody>
        {/* product summary */}
        <View style={styles.row}>
          <View style={styles.rowThumb}>
            {photo ? <FadeImage source={photo} resizeMode="contain" style={styles.thumbImg} /> : <PH label="" />}
          </View>
          <View style={styles.rowMain}>
            <Text style={styles.rowTitle}>{item ? `${item.brand}, ${item.name}` : 'Listing'}</Text>
            <Text style={text.meta}>{item ? `Size ${item.size ?? 'one size'}` : ''}</Text>
          </View>
        </View>

        <View style={styles.sec}>
          {/* offer display */}
          <View style={styles.offerWrap}>
            <Text style={[text.eyebrow, styles.offerEyebrow]}>Your offer</Text>
            <View style={styles.offerRow}>
              <Text style={styles.dollar}>$</Text>
              <Text style={styles.amount}>{amount}</Text>
            </View>
          </View>

          {/* benchmarks */}
          <View style={styles.benchRow}>
            {bench.map(([l, v]) => (
              <View key={l} style={styles.benchCell}>
                <Text style={[text.cardFrom, { fontSize: 9.5 }]}>{l}</Text>
                <Text style={styles.benchVal}>{v}</Text>
              </View>
            ))}
          </View>

          {/* quick chips */}
          <View style={styles.chipRow}>
            {QUICK.map((t, i) => {
              const on = i === active;
              return (
                <PressableScale key={t} pressScale={0.95} onPress={() => applyQuick(i)} style={[styles.fchip, on && styles.fchipOn]}>
                  <Text style={[styles.fchipText, on && styles.fchipTextOn]}>{t}</Text>
                </PressableScale>
              );
            })}
          </View>

          {/* expires field */}
          <View style={styles.field}>
            <Text style={styles.fieldLabel}>Offer expires</Text>
            <View style={styles.input}>
              <Text style={styles.inputText}>In 3 days</Text>
              <Icon.chevDown w={16} h={16} strokeWidth={2} stroke={colors.gray} />
            </View>
          </View>

          {/* respond note */}
          <View style={styles.note}>
            <Icon.bell w={17} h={17} strokeWidth={1.9} />
            <Text style={styles.noteText}>Sellers respond within 24h.</Text>
          </View>

          <Text style={[text.meta, styles.fine]}>
            You’ll only be charged if the seller accepts. Offers are binding once accepted.
          </Text>
        </View>
      </ScreenBody>

      <View style={dualCTA}>
        <Button
          label={busy ? 'Sending…' : 'Send offer'}
          onPress={submit}
          disabled={busy || !item}
          right={busy ? <ActivityIndicator color={colors.white} size="small" /> : undefined}
        />
      </View>
    </Screen>
  );
}

