// src/app/(tabs)/activity.tsx
// Real activity feed: my orders + offers I made, when signed in. Signed-out
// shows a friendly prompt to log in. Filter chips narrow the feed.

import { useCallback, useEffect, useState } from 'react';
import { View, Text, Pressable, StyleSheet, ActivityIndicator } from 'react-native';
import { useFocusEffect, useRouter } from 'expo-router';

import { Screen, ScreenBody, TopBar, Button } from '@/ls/ui';
import { Icon } from '@/ls/icons';
import { colors, text, fonts } from '@/ls/theme';
import { orders as ordersApi, offers as offersApi, type ApiOrder, type ApiOffer } from '@/ls/api';
import { useSession } from '@/ls/session';

type NotifType = 'alert' | 'offer' | 'ship' | 'sold';

type Notif = {
  type: NotifType;
  title: string;
  body: string;
  time: string;
  listingId?: string;
  group: 'Offers' | 'Orders';
};

const ICON_FOR: Record<NotifType, (typeof Icon)[keyof typeof Icon]> = {
  alert: Icon.bell,
  offer: Icon.tag,
  ship: Icon.truck,
  sold: Icon.box,
};

const FILTERS = ['All', 'Offers', 'Orders'] as const;

function ago(iso: string): string {
  const then = new Date(iso).getTime();
  const mins = Math.max(0, Math.floor((Date.now() - then) / 60000));
  if (mins < 1) return 'now';
  if (mins < 60) return `${mins}m`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}h`;
  return `${Math.floor(hrs / 24)}d`;
}

function orderTitle(o: ApiOrder): string {
  switch (o.status) {
    case 'shipped':
      return 'Shipped';
    case 'delivered':
      return 'Delivered';
    case 'cancelled':
      return 'Order cancelled';
    default:
      return 'Order confirmed';
  }
}

function orderType(o: ApiOrder): NotifType {
  if (o.status === 'shipped' || o.status === 'delivered') return 'ship';
  return 'sold';
}

function offerTitle(o: ApiOffer): string {
  switch (o.status) {
    case 'accepted':
      return 'Offer accepted';
    case 'declined':
      return 'Offer declined';
    case 'expired':
      return 'Offer expired';
    default:
      return 'Offer sent';
  }
}

export default function ActivityTab() {
  const router = useRouter();
  const { signedIn } = useSession();
  const [filter, setFilter] = useState(0);
  const [loading, setLoading] = useState(true);
  const [items, setItems] = useState<Notif[]>([]);

  const load = useCallback(async () => {
    if (!signedIn) {
      setItems([]);
      setLoading(false);
      return;
    }
    setLoading(true);
    const [ordersRes, offersRes] = await Promise.all([
      ordersApi.list().catch(() => ({ orders: [] as ApiOrder[] })),
      offersApi.listMine().catch(() => ({ offers: [] as ApiOffer[] })),
    ]);

    const orderNotifs: Notif[] = ordersRes.orders.map((o) => ({
      type: orderType(o),
      title: orderTitle(o),
      body: o.listing
        ? `${o.listing.brand} ${o.listing.name} · $${(o.amountCents / 100).toFixed(0)}`
        : `Order total $${(o.amountCents / 100).toFixed(0)}`,
      time: ago(o.createdAt),
      listingId: o.listingId,
      group: 'Orders',
    }));

    const offerNotifs: Notif[] = offersRes.offers.map((o) => ({
      type: 'offer',
      title: offerTitle(o),
      body: o.listing
        ? `${o.listing.brand} ${o.listing.name} · your offer $${(o.amountCents / 100).toFixed(0)}`
        : `Your offer $${(o.amountCents / 100).toFixed(0)}`,
      time: ago(o.createdAt),
      listingId: o.listingId,
      group: 'Offers',
    }));

    setItems([...orderNotifs, ...offerNotifs]);
    setLoading(false);
  }, [signedIn]);

  useEffect(() => {
    load();
  }, [load]);

  // Refresh when the tab regains focus (e.g. right after placing an order).
  useFocusEffect(
    useCallback(() => {
      load();
    }, [load]),
  );

  const visible = items.filter((it) => {
    if (filter === 0) return true;
    return it.group === FILTERS[filter];
  });

  return (
    <Screen>
      <TopBar title="Activity" />

      {/* filter bar */}
      <View style={styles.filterbar}>
        {FILTERS.map((t, i) => {
          const active = i === filter;
          return (
            <Pressable
              key={t}
              onPress={() => setFilter(i)}
              style={[styles.fchip, active && styles.fchipActive]}
            >
              <Text style={[styles.fchipText, active && styles.fchipTextActive]}>{t}</Text>
            </Pressable>
          );
        })}
      </View>

      <ScreenBody>
        {!signedIn ? (
          <View style={styles.emptyWrap}>
            <Text style={styles.emptyTitle}>Track your orders and offers</Text>
            <Text style={styles.emptyBody}>Log in to see your activity here.</Text>
            <View style={styles.emptyCta}>
              <Button small label="Log in" onPress={() => router.push('/login')} />
            </View>
          </View>
        ) : loading ? (
          <View style={styles.loadingWrap}>
            <ActivityIndicator color={colors.black} />
          </View>
        ) : visible.length === 0 ? (
          <View style={styles.emptyWrap}>
            <Text style={styles.emptyTitle}>Nothing here yet</Text>
            <Text style={styles.emptyBody}>Your offers and orders will show up here.</Text>
          </View>
        ) : (
          visible.map((it, i) => {
            const Ico = ICON_FOR[it.type];
            return (
              <Pressable
                key={i}
                style={styles.row}
                onPress={() => it.listingId && router.push(`/product/${it.listingId}`)}
              >
                <View style={styles.rowIcon}>
                  <Ico w={18} h={18} strokeWidth={1.9} />
                </View>
                <View style={styles.rowMain}>
                  <View style={styles.rowTitleLine}>
                    <Text style={styles.rowTitle}>{it.title}</Text>
                  </View>
                  <Text style={styles.rowBody}>{it.body}</Text>
                </View>
                <Text style={[text.meta, styles.rowTime]}>{it.time}</Text>
              </Pressable>
            );
          })
        )}
      </ScreenBody>
    </Screen>
  );
}

const styles = StyleSheet.create({
  filterbar: {
    flexDirection: 'row',
    gap: 8,
    paddingHorizontal: 16,
    paddingVertical: 10,
    borderBottomWidth: 1,
    borderBottomColor: colors.line,
  },
  fchip: {
    flexDirection: 'row',
    alignItems: 'center',
    height: 32,
    paddingHorizontal: 13,
    borderRadius: 999,
    borderWidth: 1,
    borderColor: colors.line,
    backgroundColor: colors.white,
  },
  fchipActive: { backgroundColor: colors.black, borderColor: colors.black },
  fchipText: {
    fontFamily: fonts.semibold,
    fontWeight: '600',
    fontSize: 12.5,
    letterSpacing: 0.01 * 12.5,
    color: colors.black,
  },
  fchipTextActive: { color: colors.white },

  loadingWrap: { paddingVertical: 48, alignItems: 'center' },
  emptyWrap: { paddingVertical: 56, paddingHorizontal: 24, alignItems: 'center', gap: 6 },
  emptyTitle: { fontFamily: fonts.bold, fontWeight: '700', fontSize: 15, color: colors.black, textAlign: 'center' },
  emptyBody: { fontFamily: fonts.regular, fontWeight: '400', fontSize: 13, color: colors.gray, textAlign: 'center' },
  emptyCta: { marginTop: 14, alignSelf: 'stretch', paddingHorizontal: 24 },

  row: {
    flexDirection: 'row',
    alignItems: 'flex-start',
    gap: 12,
    paddingHorizontal: 16,
    paddingVertical: 14,
    borderBottomWidth: 1,
    borderBottomColor: colors.line,
  },
  rowIcon: {
    width: 40,
    height: 40,
    borderRadius: 999,
    backgroundColor: colors.lightGray,
    alignItems: 'center',
    justifyContent: 'center',
    flexShrink: 0,
    marginTop: 2,
  },
  rowMain: { flex: 1, minWidth: 0, flexDirection: 'column', gap: 3 },
  rowTitleLine: { flexDirection: 'row', alignItems: 'center', gap: 7 },
  rowTitle: { fontFamily: fonts.bold, fontWeight: '700', fontSize: 14, color: colors.black },
  rowBody: { fontFamily: fonts.regular, fontWeight: '400', fontSize: 13, lineHeight: 13 * 1.4, color: '#444444' },
  rowTime: { flexShrink: 0 },
});
