import React, { useState } from 'react';
import { View, Text, Pressable, StyleSheet } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { Image as ExpoImage } from 'expo-image';
import { LinearGradient } from 'expo-linear-gradient';
import { useRouter } from 'expo-router';
import Animated, { FadeIn, FadeInDown } from 'react-native-reanimated';

import { Screen, Brand } from '@/ls/ui';
import { PressableScale } from '@/ls/motion';
import { colors, fonts, letterSpacingPx, chrome } from '@/ls/theme';

// Rotating hero pool. Static requires only (Metro can't bundle dynamic paths).
// CJ's picks: hero-4 (b/w street feet), hero-2 (light white sneakers), hero-5 (macro laces).
// Each hero carries its own focal point so the subject (the shoes) is never
// cropped out of the visible window or buried under the copy panel.
const HEROES: { src: any; focus: string }[] = [
  { src: require('../../assets/heroes/hero-4.jpg'), focus: 'center 85%' },
  { src: require('../../assets/heroes/hero-2.jpg'), focus: 'center 45%' },
  { src: require('../../assets/heroes/hero-5.jpg'), focus: 'center' },
];

// Splash / value prop. Contained hero up top (subject stays visible), fading
// into a solid black panel that holds the headline, trust row, and CTAs.
export default function SplashScreen() {
  const router = useRouter();
  const insets = useSafeAreaInsets();
  const topPad = (insets.top || chrome.statusH) + 18;
  const bottomPad = (insets.bottom || chrome.homeH) + 18;

  // Pick one hero on mount (stable for the lifetime of the screen).
  const [hero] = useState(() => HEROES[Math.floor(Math.random() * HEROES.length)]);

  const trust = ['Curated', 'Protected', 'No seller fees'];

  return (
    <Screen dark>
      {/* hero region: image owns the top ~55%, melts into black below */}
      <View style={styles.heroWrap}>
        <ExpoImage
          source={hero.src}
          contentFit="cover"
          contentPosition={hero.focus as any}
          transition={250}
          style={StyleSheet.absoluteFill}
        />
        <LinearGradient
          colors={['rgba(0,0,0,0.45)', 'rgba(0,0,0,0)', 'rgba(0,0,0,0)', '#000000']}
          locations={[0, 0.28, 0.72, 1]}
          style={StyleSheet.absoluteFill}
        />
        <Animated.View
          entering={FadeIn.duration(500)}
          style={[styles.brandRow, { paddingTop: topPad }]}
        >
          <Brand size={30} light />
        </Animated.View>
      </View>

      {/* copy panel: solid black, nothing competes with the photo */}
      <View style={styles.panel}>
        <View style={{ paddingBottom: bottomPad }}>
          <Animated.Text entering={FadeInDown.duration(500).delay(120)} style={styles.headline}>
            Big brands.{'\n'}Little soles.
          </Animated.Text>
          <Animated.Text entering={FadeInDown.duration(500).delay(220)} style={styles.sub}>
            Premium kids sneakers, less than retail. Sellers keep every dollar.
          </Animated.Text>

          <Animated.View entering={FadeInDown.duration(500).delay(300)} style={styles.trustRow}>
            {trust.map((t, i) => (
              <React.Fragment key={t}>
                <Text style={styles.trustItem}>{t}</Text>
                {i < trust.length - 1 ? (
                  <Text style={styles.trustDot}>·</Text>
                ) : null}
              </React.Fragment>
            ))}
          </Animated.View>

          {/* White CTA needs black text, foundation Button is white-on-black,
              so render the .btn shape directly here. */}
          <Animated.View entering={FadeInDown.duration(500).delay(380)}>
            <PressableScale style={styles.cta} onPress={() => router.push('/signup')}>
              <Text style={styles.ctaText}>Get started</Text>
            </PressableScale>

            <Pressable onPress={() => router.push('/login')}>
              <Text style={styles.signin}>
                Have an account? <Text style={styles.signinStrong}>Sign in</Text>
              </Text>
            </Pressable>

            <Pressable onPress={() => router.replace('/(tabs)')}>
              <Text style={styles.browse}>Browse without an account</Text>
            </Pressable>
          </Animated.View>
        </View>
      </View>
    </Screen>
  );
}

// Hero/panel split: image owns the top, copy owns the bottom. Tuned so the
// shoe subject sits in the clear zone above the fade on common phone heights.

const styles = StyleSheet.create({
  heroWrap: {
    flex: 1.2,
    backgroundColor: colors.black,
  },
  panel: {
    flex: 1,
    backgroundColor: colors.black,
    paddingHorizontal: 24,
    justifyContent: 'flex-end',
  },
  brandRow: {
    flexDirection: 'row',
    justifyContent: 'center',
  },
  headline: {
    fontFamily: fonts.extrabold,
    fontWeight: '800',
    fontSize: 38,
    lineHeight: 38 * 1.02,
    letterSpacing: letterSpacingPx(-0.02, 38),
    textTransform: 'uppercase',
    color: colors.white,
  },
  sub: {
    fontFamily: fonts.medium,
    fontWeight: '500',
    fontSize: 15,
    lineHeight: 15 * 1.5,
    color: 'rgba(255,255,255,0.82)',
    marginTop: 16,
    maxWidth: 300,
  },
  trustRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 6,
    marginVertical: 22,
  },
  trustItem: {
    fontFamily: fonts.bold,
    fontWeight: '700',
    fontSize: 10,
    letterSpacing: letterSpacingPx(0.1, 10),
    textTransform: 'uppercase',
    color: 'rgba(255,255,255,0.7)',
  },
  trustDot: {
    color: 'rgba(255,255,255,0.4)',
    fontSize: 10,
  },
  cta: {
    backgroundColor: colors.white,
    marginTop: 4,
    height: 52,
    borderRadius: 12,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
  },
  ctaText: {
    fontFamily: fonts.bold,
    fontWeight: '700',
    fontSize: 14,
    letterSpacing: letterSpacingPx(0.08, 14),
    textTransform: 'uppercase',
    color: colors.black,
  },
  signin: {
    textAlign: 'center',
    marginTop: 18,
    fontFamily: fonts.regular,
    fontWeight: '400',
    fontSize: 13.5,
    color: 'rgba(255,255,255,0.8)',
  },
  signinStrong: {
    fontFamily: fonts.bold,
    fontWeight: '700',
    color: colors.white,
  },
  browse: {
    textAlign: 'center',
    marginTop: 14,
    fontFamily: fonts.semibold,
    fontWeight: '600',
    fontSize: 12.5,
    letterSpacing: letterSpacingPx(0.02, 12.5),
    color: 'rgba(255,255,255,0.6)',
    textDecorationLine: 'underline',
  },
});
