// src/ls/social-buttons.tsx
// The "Or continue with" block: Apple + Google buttons, both self-hiding when
// unavailable. Renders nothing at all if NEITHER provider is available.
//
// - Apple uses Apple's OWN button component (AppleAuthenticationButton) so it
//   is always App Store review compliant (correct logo, wording, contrast).
// - Google uses a standard white pill with the multicolor "G" mark, matching
//   Google's branding guidelines. The Google auth HOOK lives inside
//   <GoogleButton>, which is only rendered when GOOGLE_ENABLED is true — so the
//   hook (which throws without a client id) never runs when unconfigured.

import React, { useState } from 'react';
import { View, Text, Pressable, StyleSheet, ActivityIndicator } from 'react-native';
import * as AppleAuthentication from 'expo-apple-authentication';
import Svg, { Path } from 'react-native-svg';

import { colors, fonts, letterSpacingPx } from './theme';
import {
  GOOGLE_ENABLED,
  useGoogleAuth,
  type SocialAuth,
} from './social-auth';

// Google "G" mark (official 4-color), drawn at 18x18.
function GoogleG() {
  return (
    <Svg width={18} height={18} viewBox="0 0 48 48">
      <Path
        fill="#EA4335"
        d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z"
      />
      <Path
        fill="#4285F4"
        d="M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z"
      />
      <Path
        fill="#FBBC05"
        d="M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z"
      />
      <Path
        fill="#34A853"
        d="M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.15 1.45-4.92 2.3-8.16 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z"
      />
    </Svg>
  );
}

// Isolated so the Google auth hook only mounts when a client id is configured.
function GoogleButton({ social }: { social: SocialAuth }) {
  const google = useGoogleAuth(social.finish, social.setError);
  if (!google.ready) return null;
  return (
    <Pressable
      onPress={google.start}
      disabled={google.busy}
      style={({ pressed }) => [
        styles.googleBtn,
        pressed && styles.googlePressed,
        google.busy && styles.googleBusy,
      ]}
      accessibilityRole="button"
      accessibilityLabel="Continue with Google"
    >
      {google.busy ? (
        <ActivityIndicator color={colors.black} size="small" />
      ) : (
        <>
          <GoogleG />
          <Text style={styles.googleText}>Continue with Google</Text>
        </>
      )}
    </Pressable>
  );
}

export function SocialButtons({ social }: { social: SocialAuth }) {
  const { apple, error } = social;
  // We can't read the Google hook's `ready` here (it lives in the child), so we
  // gate on config: if Google is enabled we optimistically show the block, and
  // GoogleButton renders null internally until its request is ready.
  const [googleMounted] = useState(GOOGLE_ENABLED);

  // Nothing to show at all — skip the divider and the block entirely.
  if (!apple.available && !googleMounted) {
    return error ? <Text style={styles.error}>{error}</Text> : null;
  }

  return (
    <View>
      <View style={styles.divider}>
        <View style={styles.dividerLine} />
        <Text style={styles.dividerText}>Or continue with</Text>
        <View style={styles.dividerLine} />
      </View>

      <View style={styles.stack}>
        {apple.available ? (
          <View style={styles.appleWrap}>
            <AppleAuthentication.AppleAuthenticationButton
              buttonType={AppleAuthentication.AppleAuthenticationButtonType.CONTINUE}
              buttonStyle={AppleAuthentication.AppleAuthenticationButtonStyle.BLACK}
              cornerRadius={12}
              style={styles.appleBtn}
              onPress={apple.start}
            />
            {apple.busy ? (
              <View style={styles.appleBusy} pointerEvents="none">
                <ActivityIndicator color={colors.white} size="small" />
              </View>
            ) : null}
          </View>
        ) : null}

        {googleMounted ? <GoogleButton social={social} /> : null}
      </View>

      {error ? <Text style={styles.error}>{error}</Text> : null}
    </View>
  );
}

const styles = StyleSheet.create({
  divider: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 12,
    marginVertical: 24,
  },
  dividerLine: { flex: 1, height: 1, backgroundColor: colors.line },
  dividerText: {
    fontFamily: fonts.regular,
    fontWeight: '400',
    fontSize: 10.5,
    letterSpacing: letterSpacingPx(0.08, 10.5),
    textTransform: 'uppercase',
    color: colors.gray,
  },
  stack: { flexDirection: 'column', gap: 10 },
  // Apple
  appleWrap: { position: 'relative' },
  appleBtn: { width: '100%', height: 50 },
  appleBusy: {
    ...StyleSheet.absoluteFillObject,
    alignItems: 'center',
    justifyContent: 'center',
  },
  // Google — white surface, hairline border (Google brand guidance).
  googleBtn: {
    height: 50,
    borderRadius: 12,
    borderWidth: 1,
    borderColor: colors.line,
    backgroundColor: colors.white,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    gap: 10,
  },
  googlePressed: { opacity: 0.85 },
  googleBusy: { opacity: 0.6 },
  googleText: {
    fontFamily: fonts.semibold,
    fontWeight: '600',
    fontSize: 14.5,
    color: '#3C4043',
  },
  error: {
    marginTop: 16,
    fontFamily: fonts.medium,
    fontWeight: '500',
    fontSize: 13,
    color: colors.red,
    textAlign: 'center',
  },
});
