// src/ls/session.tsx
// Lightweight auth/session state shared across screens.
//
// Browse works logged OUT. Actions that need auth (favorite, offer, checkout,
// alerts) call requireAuth() — if there is no token it routes to /signup and
// returns false, so the caller bails cleanly instead of hitting a 401.
//
// The token itself lives in storage.ts (SecureStore on native, localStorage on
// web). This context just mirrors "are we signed in + who" for the UI and keeps
// it in sync after login/signup/logout.

import React, { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';
import { useRouter } from 'expo-router';

import { auth, type ApiUser } from './api';
import { getToken } from './storage';

type SessionState = {
  /** null while we are still restoring the token on boot. */
  ready: boolean;
  user: ApiUser | null;
  signedIn: boolean;
  /** Refresh user from /auth/me using the stored token (no-op if signed out). */
  refresh: () => Promise<void>;
  /** Record a fresh login/signup result so the UI updates immediately. */
  setUser: (user: ApiUser | null) => void;
  signOut: () => Promise<void>;
};

const SessionContext = createContext<SessionState | null>(null);

export function SessionProvider({ children }: { children: React.ReactNode }) {
  const [ready, setReady] = useState(false);
  const [user, setUserState] = useState<ApiUser | null>(null);

  const refresh = useCallback(async () => {
    const token = await getToken();
    if (!token) {
      setUserState(null);
      return;
    }
    try {
      const res = await auth.me();
      setUserState(res.user);
    } catch {
      // Token invalid/expired or backend unreachable — treat as signed out.
      setUserState(null);
    }
  }, []);

  useEffect(() => {
    let alive = true;
    (async () => {
      await refresh();
      if (alive) setReady(true);
    })();
    return () => {
      alive = false;
    };
  }, [refresh]);

  const signOut = useCallback(async () => {
    await auth.logout();
    setUserState(null);
  }, []);

  const value = useMemo<SessionState>(
    () => ({
      ready,
      user,
      signedIn: !!user,
      refresh,
      setUser: setUserState,
      signOut,
    }),
    [ready, user, refresh, signOut],
  );

  return <SessionContext.Provider value={value}>{children}</SessionContext.Provider>;
}

export function useSession(): SessionState {
  const ctx = useContext(SessionContext);
  if (!ctx) throw new Error('useSession must be used within <SessionProvider>');
  return ctx;
}

/**
 * Gate for auth-only actions. Returns a function: call it before an action that
 * needs a token. If signed out it routes to /signup and returns false.
 */
export function useRequireAuth() {
  const { signedIn } = useSession();
  const router = useRouter();
  return useCallback(
    (): boolean => {
      if (signedIn) return true;
      router.push('/signup');
      return false;
    },
    [signedIn, router],
  );
}
