import React, { useEffect, useRef, useState } from 'react';
import { View, Text, Pressable, StyleSheet, TextInput, ActivityIndicator } from 'react-native';
import { useRouter } from 'expo-router';

import { Screen, ScreenBody, TopBar, Button } from '@/ls/ui';
import { Icon } from '@/ls/icons';
import { colors, fonts, text, letterSpacingPx } from '@/ls/theme';
import { auth, ApiError } from '@/ls/api';
import { useSession } from '@/ls/session';
import { useSocialAuth } from '@/ls/social-auth';
import { SocialButtons } from '@/ls/social-buttons';

// Log in. Real auth.login (token stored by the SDK). Demo creds shown so CJ can
// sign straight in as demo@littlesoles.com.
export default function LoginScreen() {
  const router = useRouter();
  const { setUser } = useSession();
  const social = useSocialAuth();

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [busy, setBusy] = useState(false);
  const [slow, setSlow] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const slowTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // After ~6s of waiting, reassure instead of looking frozen. The free-tier
  // backend can take up to a minute to wake from sleep on the first request.
  useEffect(() => {
    if (busy) {
      slowTimer.current = setTimeout(() => setSlow(true), 6000);
    } else {
      if (slowTimer.current) clearTimeout(slowTimer.current);
      setSlow(false);
    }
    return () => {
      if (slowTimer.current) clearTimeout(slowTimer.current);
    };
  }, [busy]);

  const onLogin = async () => {
    setError(null);
    if (!email.trim() || !password) {
      setError('Enter your email and password.');
      return;
    }
    setBusy(true);
    try {
      const res = await auth.login({ email: email.trim(), password });
      setUser(res.user);
      router.replace('/(tabs)');
    } catch (e) {
      if (e instanceof ApiError && e.status === 401) {
        setError('Wrong email or password. Try again.');
      } else if (e instanceof ApiError) {
        setError(e.message);
      } else {
        setError('Could not log you in. Please try again.');
      }
    } finally {
      setBusy(false);
    }
  };

  // One tap: fill the demo creds and sign straight in.
  const useDemo = async () => {
    setEmail('demo@littlesoles.com');
    setPassword('demo1234');
    setError(null);
    setBusy(true);
    try {
      const res = await auth.login({ email: 'demo@littlesoles.com', password: 'demo1234' });
      setUser(res.user);
      router.replace('/(tabs)');
    } catch (e) {
      setError(e instanceof ApiError ? e.message : 'Could not log you in. Please try again.');
    } finally {
      setBusy(false);
    }
  };

  return (
    <Screen>
      <TopBar
        left={
          <Pressable onPress={() => router.back()} hitSlop={8}>
            <Icon.chevL w={22} h={22} strokeWidth={2} />
          </Pressable>
        }
      />
      <ScreenBody contentContainerStyle={styles.body}>
        <Text style={text.hXl}>Welcome{'\n'}back</Text>
        <Text style={[text.body, styles.sub]}>Log in to pick up where you left off.</Text>

        <View style={styles.fields}>
          <View style={styles.field}>
            <Text style={styles.label}>Email</Text>
            <View style={styles.input}>
              <TextInput
                style={styles.inputText}
                value={email}
                onChangeText={setEmail}
                placeholder="you@email.com"
                placeholderTextColor={colors.gray2}
                autoCapitalize="none"
                autoCorrect={false}
                keyboardType="email-address"
              />
            </View>
          </View>
          <View style={styles.field}>
            <Text style={styles.label}>Password</Text>
            <View style={[styles.input, styles.inputBetween]}>
              <TextInput
                style={[styles.inputText, { flex: 1 }]}
                value={password}
                onChangeText={setPassword}
                placeholder="Your password"
                placeholderTextColor={colors.gray2}
                secureTextEntry
                autoCapitalize="none"
              />
              <Icon.lock w={17} h={17} strokeWidth={1.8} stroke={colors.gray} />
            </View>
          </View>
        </View>

        {error ? <Text style={styles.error}>{error}</Text> : null}
        {busy && slow ? (
          <Text style={styles.slowHint}>
            Waking up the server. First login can take up to a minute, hang tight.
          </Text>
        ) : null}

        <Button
          label={busy ? 'Logging in…' : 'Log in'}
          onPress={onLogin}
          disabled={busy}
          style={styles.loginBtn}
          right={busy ? <ActivityIndicator color={colors.white} size="small" /> : undefined}
        />

        <Pressable onPress={useDemo} hitSlop={8} style={styles.demoRow}>
          <Text style={styles.demoText}>Use the demo account</Text>
        </Pressable>

        <SocialButtons social={social} />

        <Pressable onPress={() => router.replace('/signup')} hitSlop={8} style={styles.altRow}>
          <Text style={styles.altText}>
            New here? <Text style={styles.altStrong}>Create an account</Text>
          </Text>
        </Pressable>
      </ScreenBody>
    </Screen>
  );
}

const styles = StyleSheet.create({
  body: { paddingHorizontal: 24, paddingTop: 4, paddingBottom: 24 },
  sub: { marginTop: 12 },
  fields: { flexDirection: 'column', gap: 16, marginTop: 28 },
  field: { flexDirection: 'column', gap: 7 },
  label: {
    fontFamily: fonts.bold,
    fontWeight: '700',
    fontSize: 11,
    letterSpacing: letterSpacingPx(0.1, 11),
    textTransform: 'uppercase',
    color: colors.gray,
  },
  input: {
    height: 50,
    borderWidth: 1,
    borderColor: colors.line,
    borderRadius: 11,
    paddingHorizontal: 14,
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: colors.white,
  },
  inputBetween: { justifyContent: 'space-between' },
  inputText: {
    fontFamily: fonts.medium,
    fontWeight: '500',
    fontSize: 15,
    color: colors.black,
    paddingVertical: 0,
  },
  error: {
    marginTop: 16,
    fontFamily: fonts.medium,
    fontWeight: '500',
    fontSize: 13,
    color: colors.red,
  },
  slowHint: {
    marginTop: 16,
    fontFamily: fonts.medium,
    fontWeight: '500',
    fontSize: 13,
    color: colors.gray,
  },
  loginBtn: { marginTop: 24 },
  demoRow: { marginTop: 16, alignItems: 'center' },
  demoText: {
    fontFamily: fonts.semibold,
    fontWeight: '600',
    fontSize: 13,
    color: colors.gray,
    textDecorationLine: 'underline',
  },
  altRow: { marginTop: 22, alignItems: 'center' },
  altText: { fontFamily: fonts.regular, fontWeight: '400', fontSize: 13.5, color: colors.gray },
  altStrong: { fontFamily: fonts.bold, fontWeight: '700', color: colors.black },
});
